func:
// 智能机柜 Modbus 数据仿真器
// 输出1：Holding Registers，FC16，地址0开始
// 输出2：Coils，FC15，地址0开始
// 输出3：便于调试查看的结构化对象

const now = Date.now();
let s = context.get("rackState");

if (!s) {
    s = {
        startedAt: now,
        lastAt: now,
        cabinetId: 1,
        temperature: 24.5,
        humidity: 45.0,
        inletTemp: 22.8,
        outletTemp: 27.2,
        voltage: 220.0,
        current: 3.20,
        energyKwh: 1250.0,
        fanRpm: 1800,
        doorOpenCount: 0,
        doorOpen: false,
        smokeAlarm: false,
        waterLeak: false,
        powerAlarm: false,
        fanAlarm: false,
        maintenanceMode: false
    };
}

const dtSeconds = Math.max(0.1, (now - s.lastAt) / 1000);
s.lastAt = now;

const rand = (min, max) => min + Math.random() * (max - min);
const clamp = (v, min, max) => Math.min(max, Math.max(min, v));

// 小幅随机游走，使数据看起来像真实设备，而不是完全独立的随机数
s.temperature = clamp(s.temperature + rand(-0.18, 0.18), 20.0, 38.0);
s.humidity = clamp(s.humidity + rand(-0.35, 0.35), 30.0, 75.0);
s.inletTemp = clamp(s.temperature - rand(1.0, 2.5), 18.0, 36.0);
s.outletTemp = clamp(s.temperature + rand(1.5, 4.0), 20.0, 45.0);
s.voltage = clamp(s.voltage + rand(-0.8, 0.8), 205.0, 240.0);
s.current = clamp(s.current + rand(-0.12, 0.12), 0.5, 12.0);
s.fanRpm = Math.round(clamp(s.fanRpm + rand(-45, 45), 800, 3200));

const activePowerW = Math.round(s.voltage * s.current * 0.92);
const apparentPowerVA = Math.round(s.voltage * s.current);
const loadPercent = clamp((activePowerW / 3000) * 100, 0, 100);
s.energyKwh += (activePowerW * dtSeconds) / 3600000;

// 低概率模拟门开关；告警默认由测量值推导
if (Math.random() < 0.01) {
    s.doorOpen = !s.doorOpen;
    if (s.doorOpen) s.doorOpenCount++;
}

const online = true;
const highTemp = s.temperature >= 35.0;
const highHumidity = s.humidity >= 70.0;
const overload = loadPercent >= 90.0;

// 位掩码：bit0高温、bit1高湿、bit2烟感、bit3水浸、bit4电源、bit5风扇、bit6过载
const alarmCode =
      (highTemp       ? 1  : 0)
    | (highHumidity   ? 2  : 0)
    | (s.smokeAlarm   ? 4  : 0)
    | (s.waterLeak    ? 8  : 0)
    | (s.powerAlarm   ? 16 : 0)
    | (s.fanAlarm     ? 32 : 0)
    | (overload       ? 64 : 0);

const uptimeSeconds = Math.floor((now - s.startedAt) / 1000);

// Holding Registers，均为16位无符号整数
const registers = [
    s.cabinetId,                         // HR0  机柜ID
    Math.round(s.temperature * 10),      // HR1  柜内温度，0.1°C
    Math.round(s.humidity * 10),         // HR2  湿度，0.1%RH
    Math.round(s.voltage * 10),          // HR3  电压，0.1V
    Math.round(s.current * 100),         // HR4  电流，0.01A
    activePowerW,                        // HR5  有功功率，W
    apparentPowerVA,                     // HR6  视在功率，VA
    Math.round(s.energyKwh * 10) % 65536,// HR7  累计电能低16位，0.1kWh
    s.fanRpm,                            // HR8  风扇转速，RPM
    s.doorOpenCount % 65536,             // HR9  开门累计次数
    alarmCode,                           // HR10 综合告警位掩码
    Math.round(loadPercent * 10),        // HR11 负载率，0.1%
    Math.round(s.inletTemp * 10),        // HR12 进风温度，0.1°C
    Math.round(s.outletTemp * 10),       // HR13 出风温度，0.1°C
    (uptimeSeconds >>> 16) & 0xffff,     // HR14 运行时间高16位
    uptimeSeconds & 0xffff,              // HR15 运行时间低16位
    3000,                                // HR16 额定功率，W
    350,                                 // HR17 高温阈值，0.1°C
    700,                                 // HR18 高湿阈值，0.1%RH
    1                                    // HR19 数据模型版本
];

const coils = [
    online,                 // C0 在线
    s.doorOpen,             // C1 门打开
    s.smokeAlarm,           // C2 烟感告警
    s.waterLeak,            // C3 水浸告警
    s.powerAlarm,           // C4 电源告警
    s.fanAlarm,             // C5 风扇告警
    highTemp || overload,   // C6 环境/负载严重告警
    s.maintenanceMode       // C7 维护模式
];

context.set("rackState", s);

const registerMsg = {
    topic: "rack/holding-registers",
    payload: {
        value: registers,
        fc: 16,
        unitid: 1,
        address: 0,
        quantity: registers.length
    }
};

const coilMsg = {
    topic: "rack/coils",
    payload: {
        value: coils,
        fc: 15,
        unitid: 1,
        address: 0,
        quantity: coils.length
    }
};

const viewMsg = {
    topic: "rack/telemetry",
    payload: {
        timestamp: new Date(now).toISOString(),
        cabinetId: s.cabinetId,
        temperatureC: Number(s.temperature.toFixed(1)),
        humidityRH: Number(s.humidity.toFixed(1)),
        inletTemperatureC: Number(s.inletTemp.toFixed(1)),
        outletTemperatureC: Number(s.outletTemp.toFixed(1)),
        voltageV: Number(s.voltage.toFixed(1)),
        currentA: Number(s.current.toFixed(2)),
        activePowerW,
        apparentPowerVA,
        energyKwh: Number(s.energyKwh.toFixed(1)),
        loadPercent: Number(loadPercent.toFixed(1)),
        fanRpm: s.fanRpm,
        doorOpen: s.doorOpen,
        alarmCode,
        coils,
        registers
    }
};

return [registerMsg, coilMsg, viewMsg];

const p = msg.payload || {};
const data = Array.isArray(p.data) ? p.data :
             Array.isArray(p) ? p :
             (Array.isArray(msg.data) ? msg.data : []);

if (data.length < 20) {
    msg.payload = { error: "Holding Register返回长度不足", raw: msg.payload };
    return msg;
}

const uptimeSeconds = ((data[14] << 16) >>> 0) + data[15];

msg.payload = {
    cabinetId: data[0],
    temperatureC: data[1] / 10,
    humidityRH: data[2] / 10,
    voltageV: data[3] / 10,
    currentA: data[4] / 100,
    activePowerW: data[5],
    apparentPowerVA: data[6],
    energyLowWordKwh: data[7] / 10,
    fanRpm: data[8],
    doorOpenCount: data[9],
    alarmCode: data[10],
    loadPercent: data[11] / 10,
    inletTemperatureC: data[12] / 10,
    outletTemperatureC: data[13] / 10,
    uptimeSeconds,
    ratedPowerW: data[16],
    highTemperatureThresholdC: data[17] / 10,
    highHumidityThresholdRH: data[18] / 10,
    modelVersion: data[19]
};
return msg;

const p = msg.payload || {};
const data = Array.isArray(p.data) ? p.data :
             Array.isArray(p) ? p :
             (Array.isArray(msg.data) ? msg.data : []);

msg.payload = {
    online: Boolean(data[0]),
    doorOpen: Boolean(data[1]),
    smokeAlarm: Boolean(data[2]),
    waterLeak: Boolean(data[3]),
    powerAlarm: Boolean(data[4]),
    fanAlarm: Boolean(data[5]),
    criticalAlarm: Boolean(data[6]),
    maintenanceMode: Boolean(data[7])
};
return msg;
